//! Pure-Rust re-implementation of the `inflection` C++ library API.
//!
//! Mirrors `inflection::Inflector` static methods: pluralize, singularize,
//! camelize, underscore, classify, tableize, humanize, dasherize, upcase,
//! downcase. Behaviour was reverse-engineered from the reference binary.

mod case;
mod singular;

pub struct Inflector;

impl Inflector {
    /// Kept for API parity with the C++ library (no-op: rules are
    /// compile-time constants in this implementation).
    pub fn initialize() {}

    /// Naive pluralization: appends "s" (empty string stays empty).
    pub fn pluralize(word: &str) -> String {
        if word.is_empty() {
            String::new()
        } else {
            let mut s = String::with_capacity(word.len() + 1);
            s.push_str(word);
            s.push('s');
            s
        }
    }

    /// Rule-based singularization (see `singular` module).
    pub fn singularize(word: &str) -> String {
        singular::singularize(word)
    }

    /// lowerCamelCase: first segment untouched, later segments capitalized.
    pub fn camelize(word: &str) -> String {
        case::camelize(word, false)
    }

    /// snake_case: inserts '_' before every uppercase letter (except the
    /// very first character) and lowercases it. No acronym collapsing.
    pub fn underscore(word: &str) -> String {
        case::underscore(word)
    }

    /// "user_accounts" -> "UserAccount"
    pub fn classify(word: &str) -> String {
        case::camelize(&singular::singularize(word), true)
    }

    /// "UserAccount" -> "user_accounts"
    pub fn tableize(word: &str) -> String {
        Self::pluralize(&case::underscore(word))
    }

    /// "employee_id" -> "Employee id" (underscores become spaces, first
    /// character uppercased; no "_id" stripping).
    pub fn humanize(word: &str) -> String {
        case::humanize(word)
    }

    /// "employee_id" -> "employee-id"
    pub fn dasherize(word: &str) -> String {
        case::dasherize(word)
    }

    /// ASCII-only uppercase.
    pub fn upcase(word: &str) -> String {
        case::upcase(word)
    }

    /// ASCII-only lowercase.
    pub fn downcase(word: &str) -> String {
        case::downcase(word)
    }
}

//! String case transformations (camelize, underscore, humanize, ...).
//! All case mapping is ASCII-only, matching the C++ reference built on
//! `std::toupper` / `std::tolower` in the default "C" locale.

/// Splits on '_', capitalizes the first character of every segment
/// (or every segment except the first when `upper_first` is false).
/// Empty segments contribute nothing.
pub fn camelize(word: &str, upper_first: bool) -> String {
    let mut out = String::with_capacity(word.len());
    for (i, segment) in word.split('_').enumerate() {
        if i == 0 && !upper_first {
            out.push_str(segment);
        } else {
            let mut chars = segment.chars();
            if let Some(first) = chars.next() {
                out.push(first.to_ascii_uppercase());
                out.push_str(chars.as_str());
            }
        }
    }
    out
}

pub fn underscore(word: &str) -> String {
    let mut out = String::with_capacity(word.len() + 4);
    for (i, c) in word.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

pub fn humanize(word: &str) -> String {
    let mut out = String::with_capacity(word.len());
    for (i, c) in word.chars().enumerate() {
        let c = if c == '_' { ' ' } else { c };
        if i == 0 {
            out.push(c.to_ascii_uppercase());
        } else {
            out.push(c);
        }
    }
    out
}

pub fn dasherize(word: &str) -> String {
    word.replace('_', "-")
}

pub fn upcase(word: &str) -> String {
    word.chars().map(|c| c.to_ascii_uppercase()).collect()
}

pub fn downcase(word: &str) -> String {
    word.chars().map(|c| c.to_ascii_lowercase()).collect()
}

//! Singularization rules, reverse-engineered from the reference binary.
//!
//! The original library implements a subset of the Rails singular rules as
//! case-sensitive regex replacements, applied in priority order (first match
//! wins). Notable quirks faithfully reproduced here:
//!   * no irregular nouns: "people" -> "people", "men" -> "men"
//!   * no `(m)ovies`/`([lr])ves`/`(hive)s` rules: "movies" -> "movy",
//!     "wolves" -> "wolfe", "hives" -> "hife"
//!   * `((a)naly|(b)a|...)ses$ -> \1\2sis` uses C++ capture-group numbering,
//!     so "analyses" -> "analyasis" and "databases" -> "databasis"
//!   * everything is case-sensitive: "CATS" -> "CATS", "Series" -> "Sery"

/// Drops `suffix` from the end of `word` and appends `replacement`.
fn replace_end(word: &str, suffix: &str, replacement: &str) -> String {
    let mut s = String::with_capacity(word.len() - suffix.len() + replacement.len());
    s.push_str(&word[..word.len() - suffix.len()]);
    s.push_str(replacement);
    s
}

/// Truncates `n` bytes off the end (call sites guarantee an ASCII boundary).
fn strip_end(word: &str, n: usize) -> String {
    word[..word.len() - n].to_string()
}

pub fn singularize(word: &str) -> String {
    // (quiz)zes$ -> \1
    if word.ends_with("quizzes") {
        return strip_end(word, 3);
    }
    // (matr)ices$ -> \1ix
    if word.ends_with("matrices") {
        return replace_end(word, "ices", "ix");
    }
    // (vert|ind)ices$ -> \1ex
    if word.ends_with("vertices") || word.ends_with("indices") {
        return replace_end(word, "ices", "ex");
    }
    // ^(ox)en -> \1
    if word.starts_with("oxen") {
        return replace_end(&word[4..].to_string(), "", "") + ""; // placeholder, replaced below
    }
    word.to_string()
}

mod inflection;

use inflection::Inflector;

fn main() {
    Inflector::initialize();

    // 12 API calls, using different arguments (mirrors test12.cpp)
    let args: Vec<String> = std::env::args().collect();
    let mut i = 1;
    while i < args.len() && i <= 4 {
        let word = &args[i];

        match i {
            1 => {
                println!("{}", Inflector::pluralize(word));
                println!("{}", Inflector::singularize(word));
            }
            2 => {
                println!("{}", Inflector::camelize(word));
                println!("{}", Inflector::underscore(word));
            }
            3 => {
                println!("{}", Inflector::classify(word));
                println!("{}", Inflector::tableize(word));
            }
            4 => {
                println!("{}", Inflector::humanize(word));
                println!("{}", Inflector::dasherize(word));
                println!("{}", Inflector::upcase(word));
                println!("{}", Inflector::downcase(word));
            }
            _ => {}
        }

        i += 1;
    }
}

//! Singularization rules, reverse-engineered from the reference binary.
//!
//! The original library implements a subset of the Rails singular rules as
//! case-sensitive regex replacements, applied in priority order (first match
//! wins). Notable quirks faithfully reproduced here:
//!   * no irregular nouns: "people" -> "people", "men" -> "men"
//!   * no `(m)ovies`/`([lr])ves`/`(hive)s` rules: "movies" -> "movy",
//!     "wolves" -> "wolfe", "hives" -> "hife"
//!   * `((a)naly|(b)a|...)ses$ -> \1\2sis` uses C++ capture-group numbering,
//!     so "analyses" -> "analyasis" and "databases" -> "databasis"
//!   * everything is case-sensitive: "CATS" -> "CATS", "Series" -> "Sery"

/// Drops `suffix` from the end of `word` and appends `replacement`.
fn replace_end(word: &str, suffix: &str, replacement: &str) -> String {
    let mut s = String::with_capacity(word.len() - suffix.len() + replacement.len());
    s.push_str(&word[..word.len() - suffix.len()]);
    s.push_str(replacement);
    s
}

/// Truncates `n` bytes off the end (call sites guarantee an ASCII boundary).
fn strip_end(word: &str, n: usize) -> String {
    word[..word.len() - n].to_string()
}

pub fn singularize(word: &str) -> String {
    // (quiz)zes$ -> \1
    if word.ends_with("quizzes") {
        return strip_end(word, 3);
    }
    // (matr)ices$ -> \1ix
    if word.ends_with("matrices") {
        return replace_end(word, "ices", "ix");
    }
    // (vert|ind)ices$ -> \1ex
    if word.ends_with("vertices") || word.ends_with("indices") {
        return replace_end(word, "ices", "ex");
    }
    // ^(ox)en -> \1
    if word.starts_with("oxen") {
        let mut s = String::with_capacity(word.len() - 1);
        s.push_str("ox");
        s.push_str(&word[4..]);
        return s;
    }
    // (alias|status)es$ -> \1
    if word.ends_with("aliases") || word.ends_with("statuses") {
        return strip_end(word, 2);
    }
    // (octop|vir)i$ -> \1us
    if word.ends_with("octopi") || word.ends_with("viri") {
        return replace_end(word, "i", "us");
    }
    // (cris|ax|test)es$ -> \1is
    if word.ends_with("crises") || word.ends_with("axes") || word.ends_with("testes") {
        return replace_end(word, "es", "is");
    }
    // (o)es$ -> \1
    if word.ends_with("oes") {
        return strip_end(word, 2);
    }
    // (bus)es$ -> \1
    if word.ends_with("buses") {
        return strip_end(word, 2);
    }
    // ^(m|l)ice$ -> \1ouse
    if word == "mice" {
        return "mouse".to_string();
    }
    if word == "lice" {
        return "louse".to_string();
    }
    // (x|ch|ss|sh)es$ -> \1
    if word.ends_with("xes") || word.ends_with("ches") || word.ends_with("sses") || word.ends_with("shes") {
        return strip_end(word, 2);
    }
    // (s)eries$ -> \1eries
    if word.ends_with("series") {
        return word.to_string();
    }
    // (s)pecies$ -> \1pecies
    if word.ends_with("species") {
        return word.to_string();
    }
    // ((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$ -> \1\2sis
    // With C++ capture numbering \2 is only set for the (a)naly branch,
    // yielding "analyasis"; every other branch yields "<stem>sis".
    if word.ends_with("analyses") {
        return replace_end(word, "analyses", "analyasis");
    }
    for alt in ["bases", "diagnoses", "parentheses", "prognoses", "synopses", "theses"] {
        if word.ends_with(alt) {
            return replace_end(word, "ses", "sis");
        }
    }
    // ([^aeiouy]|qu)ies$ -> \1y
    if word.ends_with("ies") {
        let b = word.as_bytes();
        if b.len() >= 4 {
            let prev = b[b.len() - 4];
            let is_vowel_y = matches!(prev, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');
            let qu = prev == b'u' && b.len() >= 5 && b[b.len() - 5] == b'q';
            if !is_vowel_y || qu {
                return replace_end(word, "ies", "y");
            }
        }
    }
    // ([^f])ves$ -> \1fe
    if word.ends_with("ves") {
        let b = word.as_bytes();
        if b.len() >= 4 && b[b.len() - 4] != b'f' {
            return replace_end(word, "ves", "fe");
        }
    }
    // ([ti])a$ -> \1um
    if word.ends_with("ta") || word.ends_with("ia") {
        return replace_end(word, "a", "um");
    }
    // (n)ews$ -> \1ews
    if word.ends_with("news") {
        return word.to_string();
    }
    // s$ -> ""
    if word.ends_with('s') {
        return strip_end(word, 1);
    }
    word.to_string()
}

